/// <summary>
/// This extension is used to hook into the printReport method.
/// </summary>
[ExtensionOf(classStr(SrsReportRunPrinter))]
final class AVADAISrsReportRunPrinter_cls_Extension
{
}

Method.Source:
/// <summary>
/// extension of printReport.
/// </summary>
public void printReport()
{
    SRSProxy            proxy = this.parmSrsProxy();

    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {
        if (printSettings.printMediumType() == SRSPrintMediumType::Archive) 
        {
            proxy.AVADAIparmCalledArchive(true);
        }
        if (printSettings.printMediumType() == SRSPrintMediumType::Printer)
        {
            // setting printer as PDF to true for exporting in report export protocol and in message queue
            printSettings.parmSendToPrinterAsPdf(true);
        }
    }


    proxy.AVADAIparmCalledRVRefreshComplete(true);

    next printReport();
}
